private static Envelope error(String connectionId, JiException exception) {
    var contract = exception.error();
    ErrorDetail.Builder detail = ErrorDetail.newBuilder()
            .setCode(contract.code().code()).putAllParameters(contract.parameters());
    contract.traceId().ifPresent(detail::setTraceId);
    contract.retryAfter().ifPresent(value -> detail.setRetryAfterMillis(value.toMillis()));
    if (contract.currentRevision().isPresent()) detail.setCurrentRevision(contract.currentRevision().getAsLong());
    return envelope(connectionId).setError(detail).build();
}

private static Envelope.Builder envelope(String connectionId) {
    return Envelope.newBuilder().setProtocolVersion(PROTOCOL_VERSION).setConnectionId(connectionId);
}
